<?php require 'config.php';admin();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='save'){$name=trim($_POST['name']??'');$cat=trim($_POST['category']??'');$price=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);if(strlen($name)<2||strlen($name)>100||strlen($cat)<2||strlen($cat)>60||$price===false||$price<=0)$error='Invalid food details.';else{if($id){$s=$db->prepare('UPDATE products SET name=?,category=?,price=? WHERE id=?');$s->execute([$name,$cat,$price,$id]);}else{$s=$db->prepare('INSERT INTO products(name,category,price) VALUES(?,?,?)');$s->execute([$name,$cat,$price]);}go('admin.php');}}elseif($action==='toggle'&&$id){$s=$db->prepare('UPDATE products SET active=1-active WHERE id=?');$s->execute([$id]);go('admin.php');}elseif($action==='status'&&$id&&in_array($_POST['status']??'',['pending','preparing','ready','completed','cancelled'],true)){$s=$db->prepare('UPDATE orders SET status=? WHERE id=?');$s->execute([$_POST['status'],$id]);go('admin.php');}}head('Admin');?><h1>Admin dashboard</h1><div class="grid"><?php foreach(['Customers'=>"SELECT COUNT(*) FROM users WHERE role='customer'",'Products'=>'SELECT COUNT(*) FROM products','Orders'=>'SELECT COUNT(*) FROM orders','Completed sales (ETB)'=>"SELECT COALESCE(SUM(total),0) FROM orders WHERE status='completed'"] as $label=>$sql):?><article class="card"><h2><?=h($db->query($sql)->fetchColumn())?></h2><?=h($label)?></article><?php endforeach;?></div><h2>Add food</h2><section class="card"><p><?=h($error)?></p><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="save"><label>Name<input name="name" required maxlength="100"></label><label>Category<input name="category" required maxlength="60"></label><label>Price ETB<input type="number" name="price" min="0.01" step="0.01" required></label><button>Add food</button></form></section><h2>Manage menu</h2><div class="grid"><?php foreach($db->query('SELECT * FROM products ORDER BY id DESC') as $p):?><article class="card"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=h($p['id'])?>"><label>Name<input name="name" value="<?=h($p['name'])?>" maxlength="100" required></label><label>Category<input name="category" value="<?=h($p['category'])?>" maxlength="60" required></label><label>Price<input type="number" name="price" min="0.01" step="0.01" value="<?=h($p['price'])?>" required></label><button>Save</button></form><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=h($p['id'])?>"><button class="secondary"><?= $p['active']?'Hide':'Show'?></button></form></article><?php endforeach;?></div><h2>Manage orders</h2><div class="table"><table><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th></tr><?php foreach($db->query('SELECT o.*,u.name FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC') as $o):?><tr><td>#<?=h($o['id'])?></td><td><?=h($o['name'])?></td><td>ETB <?=h($o['total'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=h($o['id'])?>"><select name="status"><?php foreach(['pending','preparing','ready','completed','cancelled'] as $st):?><option value="<?=h($st)?>" <?=$o['status']===$st?'selected':''?>><?=h($st)?></option><?php endforeach;?></select><button>Save</button></form></td></tr><?php endforeach;?></table></div><?php foot();?>
